import re
from datetime import datetime

INTESTAZIONE = re.compile(r"^#\s*(\w+)\s*:\s*(.+?)\s*$")


def _num(s):
    return float(s.strip().replace(",", "."))


def leggi_file(testo):
    meta, forze = {}, []
    for riga in testo.splitlines():
        if m := INTESTAZIONE.match(riga):
            meta[m[1].lower()] = m[2]
        elif riga.strip() and not riga.startswith("t;"):
            forze.append(_num(riga.split(";")[1]))
    for chiave in ("provino", "materiale", "data", "a0"):
        if chiave not in meta:
            raise ValueError(f"intestazione incompleta: manca {chiave}")
    if not forze:
        raise ValueError("nessuna misura")
    return {
        "provino": meta["provino"],
        "materiale": meta["materiale"],
        "data": datetime.strptime(meta["data"], "%d/%m/%Y").date(),
        "A0": _num(meta["a0"]),
        "Fmax": max(forze),
    }
